import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Gemini Family Cookbook","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/gemini/gemini-cookbook.md","filePath":"products/ai-coding/gemini/gemini-cookbook.md","lastUpdated":1787048027000}'),n={name:"products/ai-coding/gemini/gemini-cookbook.md"};function o(r,e,l,h,d,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="gemini-family-cookbook" tabindex="-1">Gemini Family Cookbook <a class="header-anchor" href="#gemini-family-cookbook" aria-label="Permalink to &quot;Gemini Family Cookbook&quot;">​</a></h1><blockquote><p>Recipes by scenario. Each one starts from a concrete situation, then says which product to use, how to do it, and where the traps are.</p><p>For concept definitions see the <a href="./gemini-glossary.html">glossary</a>; for commands and config keys see the <a href="./gemini-cheatsheet.html">cheatsheet</a>. This page does not repeat the cheatsheet tables.</p></blockquote><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to &quot;Contents&quot;">​</a></h2><ul><li><a href="#everyday-development">Everyday development</a><ul><li><a href="#_1-build-or-type-errors-and-you-want-ai-to-read-the-log">1. Build or type errors, and you want AI to read the log</a></li><li><a href="#_2-wire-an-ai-judgement-into-a-script-or-ci">2. Wire an AI judgement into a script or CI</a></li><li><a href="#_3-the-agent-broke-a-batch-of-files-and-you-want-to-go-back">3. The agent broke a batch of files and you want to go back</a></li><li><a href="#_4-resuming-the-context-from-yesterday">4. Resuming the context from yesterday</a></li></ul></li><li><a href="#constraining-the-agent">Constraining the agent</a><ul><li><a href="#_5-you-repeat-the-project-conventions-every-time">5. You repeat the project conventions every time</a></li><li><a href="#_6-you-have-a-fixed-procedure-worth-reusing">6. You have a fixed procedure worth reusing</a></li><li><a href="#_7-separating-hard-rules-from-project-context">7. Separating hard rules from project context</a></li></ul></li><li><a href="#extending-capability">Extending capability</a><ul><li><a href="#_8-letting-the-agent-query-github-or-drive-a-browser">8. Letting the agent query GitHub or drive a browser</a></li><li><a href="#_9-you-cloned-an-unfamiliar-repo-and-do-not-want-its-config-applied">9. You cloned an unfamiliar repo and do not want its config applied</a></li></ul></li><li><a href="#large-tasks">Large tasks</a><ul><li><a href="#_10-dependency-upgrades-slow-and-mechanical">10. Dependency upgrades, slow and mechanical</a></li><li><a href="#_11-cross-module-refactor-that-needs-verification-as-it-goes">11. Cross-module refactor that needs verification as it goes</a></li><li><a href="#_12-having-ai-read-the-whole-repository-for-an-audit">12. Having AI read the whole repository for an audit</a></li></ul></li><li><a href="#other">Other</a><ul><li><a href="#_13-a-clickable-prototype-fast">13. A clickable prototype, fast</a></li><li><a href="#_14-you-got-google-cloud-credit-and-worry-about-overspending">14. You got Google Cloud credit and worry about overspending</a></li><li><a href="#_15-your-team-has-data-compliance-requirements">15. Your team has data compliance requirements</a></li></ul></li></ul><h2 id="everyday-development" tabindex="-1">Everyday development <a class="header-anchor" href="#everyday-development" aria-label="Permalink to &quot;Everyday development&quot;">​</a></h2><h3 id="_1-build-or-type-errors-and-you-want-ai-to-read-the-log" tabindex="-1">1. Build or type errors, and you want AI to read the log <a class="header-anchor" href="#_1-build-or-type-errors-and-you-want-ai-to-read-the-log" aria-label="Permalink to &quot;1. Build or type errors, and you want AI to read the log&quot;">​</a></h3><p><strong>Use</strong>: Gemini CLI headless mode (Standard / Enterprise or an API key). Individual accounts should use the <a href="./antigravity.html">Antigravity</a> CLI surface; follow the official Antigravity CLI docs for the pipe syntax.</p><p>Do not copy-paste the error into a chat window. Hand over stderr directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Vite / Webpack build failure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gemini</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;analyse the build error, name the root cause and the smallest fix&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># TypeScript emitting dozens of errors at once</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --noEmit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gemini</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;group these type errors by root cause, most impactful first&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Failing tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gemini</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;are these failures all the same cause?&quot;</span></span></code></pre></div><p><strong>Key point</strong>: you must write <code>2&gt;&amp;1</code>. Most build tools write errors to stderr, so a bare <code>|</code> pipes nothing.</p><p><strong>Do not</strong>: dump the whole <code>node_modules</code> log in. Truncate with <code>tail -100</code> first — the head and tail are enough to identify a root cause.</p><h3 id="_2-wire-an-ai-judgement-into-a-script-or-ci" tabindex="-1">2. Wire an AI judgement into a script or CI <a class="header-anchor" href="#_2-wire-an-ai-judgement-into-a-script-or-ci" aria-label="Permalink to &quot;2. Wire an AI judgement into a script or CI&quot;">​</a></h3><p><strong>Use</strong>: <code>-p</code> together with <code>--output-format json</code>.</p><p>The value of headless mode is not saving one click; it is that <code>gemini</code> becomes an ordinary Unix command a script can consume:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gemini</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;does this diff introduce an obvious security problem?&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>Extract fields from the JSON with <code>jq</code>, then decide the exit code.</p><p><strong>Key point</strong>: running AI in a script means non-deterministic output. Make it emit a <strong>structured judgement</strong> (yes/no, a severity level) rather than free text you then regex.</p><p><strong>Do not</strong>: let an agent auto-edit code in CI and merge straight away. AI in CI should only produce information; leave the edits to a product that produces a pull request, like <a href="#_10-dependency-upgrades-slow-and-mechanical">Jules</a>, so human review stays in the loop.</p><h3 id="_3-the-agent-broke-a-batch-of-files-and-you-want-to-go-back" tabindex="-1">3. The agent broke a batch of files and you want to go back <a class="header-anchor" href="#_3-the-agent-broke-a-batch-of-files-and-you-want-to-go-back" aria-label="Permalink to &quot;3. The agent broke a batch of files and you want to go back&quot;">​</a></h3><p><strong>Use</strong>: Gemini CLI checkpoints. <strong>Off by default, so turn them on first</strong>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ~/.gemini/settings.json or a project-local .gemini/settings.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;general&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;checkpointing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Once enabled, the CLI snapshots before each file modification and <code>/restore</code> rolls back.</p><p><strong>Key point</strong>: checkpoints and Git do not solve the same problem. <code>git checkout .</code> also throws away the edits you made by hand; a checkpoint has the granularity of &quot;just before the agent touched anything&quot;. You want both.</p><p><strong>Do not</strong>: skip commits because checkpointing is on. A checkpoint is short-term undo, not history.</p><h3 id="_4-resuming-the-context-from-yesterday" tabindex="-1">4. Resuming the context from yesterday <a class="header-anchor" href="#_4-resuming-the-context-from-yesterday" aria-label="Permalink to &quot;4. Resuming the context from yesterday&quot;">​</a></h3><p><strong>Use</strong>: Gemini CLI sessions. Sessions are kept indefinitely by default.</p><p>They pile up over time, so let configuration clean them:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;general&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;sessionRetention&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;maxAge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;30d&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;maxCount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>minRetention</code> defaults to <code>&quot;1d&quot;</code> and is the floor that stops very recent sessions from being deleted.</p><p>Resume with <code>gemini --resume</code> (latest), <code>gemini --resume 2</code> (index) or <code>gemini --resume &lt;id&gt;</code>. Official: <a href="https://geminicli.com/docs/cli/session-management/" target="_blank" rel="noreferrer">Session management</a>.</p><p><strong>Key point</strong>: resuming a session restores the <strong>conversation</strong>, not the <strong>files</strong>. Code state comes from Git or <a href="#_3-the-agent-broke-a-batch-of-files-and-you-want-to-go-back">checkpoints</a>.</p><h2 id="constraining-the-agent" tabindex="-1">Constraining the agent <a class="header-anchor" href="#constraining-the-agent" aria-label="Permalink to &quot;Constraining the agent&quot;">​</a></h2><h3 id="_5-you-repeat-the-project-conventions-every-time" tabindex="-1">5. You repeat the project conventions every time <a class="header-anchor" href="#_5-you-repeat-the-project-conventions-every-time" aria-label="Permalink to &quot;5. You repeat the project conventions every time&quot;">​</a></h3><p><strong>Use</strong>: put the invariants in a rules file instead of restating them.</p><p>Which file depends on which product — the three are not interchangeable:</p><table tabindex="0"><thead><tr><th>Product</th><th>Where to write it</th></tr></thead><tbody><tr><td>Gemini CLI</td><td><code>GEMINI.md</code></td></tr><tr><td>Antigravity</td><td>global <code>~/.gemini/GEMINI.md</code>, workspace <code>.agents/rules</code> directory</td></tr><tr><td>Jules</td><td><code>AGENTS.md</code> at the repository root</td></tr></tbody></table><p>Antigravity workspace rules support four activation modes (Manual / Always On / Model Decision / Glob). <strong>Prefer Glob</strong>: let &quot;React component conventions&quot; load only when the path matches <code>src/**/*.tsx</code> instead of sitting in context permanently as Always On.</p><p><strong>Key point</strong>: the limit is 12,000 characters per rule file. When you hit it, split the file and cross-reference with <code>@filename</code> rather than compressing the wording.</p><p><strong>Do not</strong>: paste your whole coding standard in. Rules should only carry the few things <strong>the agent actually gets wrong</strong>. It already knows to write semicolons.</p><h3 id="_6-you-have-a-fixed-procedure-worth-reusing" tabindex="-1">6. You have a fixed procedure worth reusing <a class="header-anchor" href="#_6-you-have-a-fixed-procedure-worth-reusing" aria-label="Permalink to &quot;6. You have a fixed procedure worth reusing&quot;">​</a></h3><p><strong>Use</strong>: a skill (the model decides when to apply it) or a workflow (you trigger it explicitly).</p><p>A skill is a <strong>directory</strong>, not a single file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.agents/skills/release-flow/</span></span>
<span class="line"><span>└── SKILL.md          # description required in the frontmatter, name optional</span></span></code></pre></div><p>Because it is a directory, you can ship scripts, templates and sample data next to <code>SKILL.md</code> and reference them from it.</p><p>Workflows are invoked as <code>/&lt;workflow-name&gt;</code>.</p><p><strong>How to choose</strong>: want the model to judge whether it applies? Write a skill, and phrase <code>description</code> as a trigger condition (&quot;when a release needs cutting…&quot;) rather than a title (&quot;release process&quot;). Want to pick the moment yourself? Write a workflow.</p><p><strong>Do not</strong>: write a flat <code>.agents/skills/release-flow.md</code>; that is not recognised as a skill. <code>.agent/skills</code> (singular) exists only for backward compatibility — use <code>.agents/skills</code> for anything new.</p><h3 id="_7-separating-hard-rules-from-project-context" tabindex="-1">7. Separating hard rules from project context <a class="header-anchor" href="#_7-separating-hard-rules-from-project-context" aria-label="Permalink to &quot;7. Separating hard rules from project context&quot;">​</a></h3><p><strong>Use</strong>: the division of labour between <code>system.md</code> and <code>GEMINI.md</code> in Gemini CLI.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GEMINI_SYSTEM_MD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">true        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># once enabled, .gemini/system.md is read</span></span></code></pre></div><p>You can also point it at an absolute path elsewhere. When it is active the UI shows a <code>|⌐■_■|</code> indicator — <strong>seeing that marker means the system prompt has been replaced</strong>, which is the first thing to check when behaviour looks off.</p><p>The split:</p><ul><li><code>.gemini/system.md</code>: non-negotiable operating rules — safety boundaries, tool-use protocol, approval mechanics</li><li><code>GEMINI.md</code>: role, goals, methodology, project context</li></ul><p><strong>Key point</strong>: <code>system.md</code> <strong>replaces</strong> the default system prompt rather than appending to it. Write too little and the CLI loses its built-in tool-use protocol, which makes it worse, not better.</p><h2 id="extending-capability" tabindex="-1">Extending capability <a class="header-anchor" href="#extending-capability" aria-label="Permalink to &quot;Extending capability&quot;">​</a></h2><h3 id="_8-letting-the-agent-query-github-or-drive-a-browser" tabindex="-1">8. Letting the agent query GitHub or drive a browser <a class="header-anchor" href="#_8-letting-the-agent-query-github-or-drive-a-browser" aria-label="Permalink to &quot;8. Letting the agent query GitHub or drive a browser&quot;">​</a></h3><p><strong>Use</strong>: MCP, installed through an extension in Gemini CLI:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gemini</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extensions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/github/github-mcp-server</span></span></code></pre></div><p>Available extensions are listed in the <a href="https://geminicli.com/extensions/" target="_blank" rel="noreferrer">official gallery</a>.</p><p><strong>Key point</strong>: the repository URL must <strong>include the organisation name</strong>. <code>https://github.com/github-mcp-server</code>, which omits it, cannot install — that wrong form appeared in older docs.</p><p><strong>Credentials</strong>: MCP servers often need a token. Put it in an environment variable or <code>.gemini/.env</code>, and make sure <code>.gemini/.env</code> is in <code>.gitignore</code>.</p><p><strong>Do not</strong>: type the token as a command-line argument. It lands in shell history and shows up in the process list.</p><h3 id="_9-you-cloned-an-unfamiliar-repo-and-do-not-want-its-config-applied" tabindex="-1">9. You cloned an unfamiliar repo and do not want its config applied <a class="header-anchor" href="#_9-you-cloned-an-unfamiliar-repo-and-do-not-want-its-config-applied" aria-label="Permalink to &quot;9. You cloned an unfamiliar repo and do not want its config applied&quot;">​</a></h3><p><strong>Use</strong>: folder trust.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;security&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;folderTrust&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>With this on, project-level settings and custom commands in untrusted directories do not take effect. The trust list lives in <code>~/.gemini/trustedFolders.json</code>.</p><p><strong>Why it matters</strong>: <code>.gemini/settings.json</code> and custom commands travel with the repository. Starting an agent inside an unfamiliar repo means someone else&#39;s configuration runs first.</p><p><strong>Key point</strong>: trust governs <strong>whose configuration is loaded</strong>, not <strong>what execution can reach</strong>. The latter is the sandbox&#39;s job; do not conflate the two.</p><blockquote><p>⚠️ Older docs contained the config keys <code>security.allowedCommands</code>, <code>security.deniedCommands</code>, <code>security.sandboxMode</code>, <code>requireBranch</code> and <code>allowedBranchPattern</code>. None of them exist in the <a href="https://github.com/google-gemini/gemini-cli/blob/main/schemas/settings.schema.json" target="_blank" rel="noreferrer">official schema</a>. For command allowlisting, see the <a href="https://geminicli.com/docs/core/policy-engine/" target="_blank" rel="noreferrer">policy engine</a>.</p></blockquote><h2 id="large-tasks" tabindex="-1">Large tasks <a class="header-anchor" href="#large-tasks" aria-label="Permalink to &quot;Large tasks&quot;">​</a></h2><h3 id="_10-dependency-upgrades-slow-and-mechanical" tabindex="-1">10. Dependency upgrades, slow and mechanical <a class="header-anchor" href="#_10-dependency-upgrades-slow-and-mechanical" aria-label="Permalink to &quot;10. Dependency upgrades, slow and mechanical&quot;">​</a></h3><p><strong>Use</strong>: <a href="./jules.html">Jules</a>. It clones and executes the repo in a cloud VM, produces a plan for your approval first, and ends with a pull request.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @google/jules</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jules</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                   # interactive board, includes side-by-side diffs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">owner/rep</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;upgrade React to 19 and fix the breaking changes&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # check progress</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # pull the result locally</span></span></code></pre></div><p><strong>Write <code>AGENTS.md</code> first</strong>: Jules is not sitting next to you, so it needs to know up front how to install dependencies, how to run tests, and which directories are off limits. Skip this and the output quality drops noticeably.</p><p><strong>The parallelism trap</strong>: <code>jules remote new --parallel &lt;number&gt;</code> runs several tasks at once, but <strong>tasks touching the same files collide</strong>. Split work along directory or module boundaries, not by &quot;these feel convenient together&quot;.</p><p><strong>Do not</strong>: the npm package is <code>@google/jules</code>. The <code>@google/jules-tools</code> package and the <code>jules status</code>, <code>jules task list</code>, <code>jules pr apply</code> and <code>--issue=</code> forms seen in older docs do not exist.</p><h3 id="_11-cross-module-refactor-that-needs-verification-as-it-goes" tabindex="-1">11. Cross-module refactor that needs verification as it goes <a class="header-anchor" href="#_11-cross-module-refactor-that-needs-verification-as-it-goes" aria-label="Permalink to &quot;11. Cross-module refactor that needs verification as it goes&quot;">​</a></h3><p><strong>Use</strong>: <a href="./antigravity.html">Antigravity</a>.</p><p>The reason is that two of its mechanisms map onto exactly this kind of risk: <strong>artifacts</strong> let you read the plan before it starts, and <strong>asynchronous subagents</strong> let it read several modules in parallel without blowing out a single context window.</p><p><strong>How</strong>: have it emit a plan artifact → read it and veto the parts pointing the wrong way → then let it execute → use its verification record to decide how much to trust the result.</p><p><strong>Key point</strong>: concurrency means changes arrive from several directions. Make sure the workspace is clean before you start, or you will not be able to tell afterwards which change came from where.</p><p><strong>Picking an entry point</strong>: desktop suits interactive exploration, the CLI slots into existing scripts, the SDK embeds in your own automation. Rules and skills are shared across surfaces, so there is nothing to reconfigure.</p><h3 id="_12-having-ai-read-the-whole-repository-for-an-audit" tabindex="-1">12. Having AI read the whole repository for an audit <a class="header-anchor" href="#_12-having-ai-read-the-whole-repository-for-an-audit" aria-label="Permalink to &quot;12. Having AI read the whole repository for an audit&quot;">​</a></h3><p><strong>Use</strong>: <a href="./ai-studio.html">AI Studio</a>, where you control the model and its parameters directly.</p><p>The only context figure quotable from the official subscription comparison is: <strong>1,000,000-token extended context for Pro and above</strong>.</p><p><strong>How</strong>:</p><ol><li>Feed only <strong>source code and type definitions</strong>; exclude <code>node_modules</code>, <code>dist</code>, lock files and build output</li><li>Phrase the question as an enumerable checklist (&quot;find every place that manipulates the DOM directly&quot;) instead of an open-ended &quot;review the code quality&quot;</li><li>Ask one class of question at a time. Mixing them makes every answer shallow</li></ol><p><strong>Key point</strong>: a long context does not mean uniform attention. Content at the beginning and end is used better than the middle, so put the most important constraints and questions at both ends.</p><p><strong>Lower the temperature</strong>: an audit wants stable reproducibility, not creativity.</p><h2 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h2><h3 id="_13-a-clickable-prototype-fast" tabindex="-1">13. A clickable prototype, fast <a class="header-anchor" href="#_13-a-clickable-prototype-fast" aria-label="Permalink to &quot;13. A clickable prototype, fast&quot;">​</a></h3><p><strong>Use</strong>: <a href="./canvas.html">Canvas</a>, which gives you a workspace inside the conversation with no local project to set up.</p><p><strong>Go in layers, do not ask for everything at once</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Layer 1: DOM structure + basic interaction   → confirm the logic is on track</span></span>
<span class="line"><span>Layer 2: apply the design system             → keep the code tidy</span></span>
<span class="line"><span>Layer 3: move into a real project for types</span></span>
<span class="line"><span>         and tests                           → this step leaves Canvas</span></span></code></pre></div><p><strong>Key point</strong>: Canvas output is a prototype. Treat it as the fastest path to validating an idea, not as a source of production code. If you need a video rather than a clickable page, use <a href="./flow.html">Google Flow</a>.</p><p><strong>Do not</strong>: ask it for a full-size application with complete business logic in one shot. Once the feedback loop gets long, you lose the information about which step went wrong.</p><h3 id="_14-you-got-google-cloud-credit-and-worry-about-overspending" tabindex="-1">14. You got Google Cloud credit and worry about overspending <a class="header-anchor" href="#_14-you-got-google-cloud-credit-and-worry-about-overspending" aria-label="Permalink to &quot;14. You got Google Cloud credit and worry about overspending&quot;">​</a></h3><p>The Google AI Pro tier provides US$10/month of Google Cloud credit through the Google Developer Program (Ultra 5x gets US$40, Ultra 20x gets US$100).</p><p><strong>The first thing to do is set a budget, not start calling APIs</strong>:</p><ol><li>GCP console → Billing → Budgets &amp; alerts</li><li>Create a budget matching the credit amount</li><li>Turn on alerts (50% / 90% / 100% is a reasonable set)</li></ol><p><strong>Key point</strong>: credit is money you were given, <strong>not a hard cap</strong>. Anything beyond it bills normally to your attached payment method.</p><p><strong>Do not</strong>: run batch scripts without a budget in place. A single long-context call costs far more than an interactive exchange.</p><h3 id="_15-your-team-has-data-compliance-requirements" tabindex="-1">15. Your team has data compliance requirements <a class="header-anchor" href="#_15-your-team-has-data-compliance-requirements" aria-label="Permalink to &quot;15. Your team has data compliance requirements&quot;">​</a></h3><p><strong>Use</strong>: the enterprise editions of <a href="./code-assist.html">Code Assist</a>. It is the one product in the family whose primary selling point is compliance — the official opening addresses &quot;organizations with strict data security and compliance requirements&quot;, and it explicitly offers VPC Service Controls and IP indemnification.</p><p><strong>Editions</strong>: Standard / Enterprise (the individual free tier stopped on 2026-06-18), supporting VS Code / JetBrains / Android Studio.</p><p><strong>Key point</strong>: the compliance capabilities are attached to the <strong>edition</strong>, not to your personal subscription. A personal AI Pro subscription does not turn Code Assist into the enterprise product.</p><blockquote><p>⚠️ Older docs contained a <code>codeAssist.agentMode</code> configuration block (with <code>enabled</code> / <code>autoApprove</code> / <code>requireSpecConfirmation</code>). Code Assist does have an agent mode, but <strong>that JSON key does not exist in the official documentation</strong> — follow the official docs for how to enable it.</p></blockquote><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./gemini-cheatsheet.html">Cheatsheet</a> — commands, config keys, model status, subscription tiers</li><li><a href="./gemini-glossary.html">Glossary</a> — concept definitions and how they relate</li><li><a href="./index.html">Learning map</a> — what to learn in what order</li></ul>`,109)])])}const y=t(n,[["render",o]]);export{m as __pageData,y as default};
